import {
	getChromeLocalStorageItem,
	getChromeSyncStorageItem,
	setChromeLocalStorageItem,
	setChromeSyncStorageItem,
} from "./storage";

const config = {
	GA_ENDPOINT: "https://www.google-analytics.com/mp/collect",
	GA_DEBUG_ENDPOINT: "https://www.google-analytics.com/debug/mp/collect",
	GA_MEASUREMENT_ID: "G-V3VSP7EQBQ",
	GA_API_SECRET: "Ociti_pnRfa797JSsfwD3g",
	GA_DEFAULT_ENGAGEMENT_TIME_MSEC: 100,
	GA_SESSION_EXPIRATION_IN_MIN: 5,
};

export const fireEvent = async (name, data = {}) => {
	const storageKeys = {
		clientId: "clientId",
		userId: "userId",
		sessionData: "sessionData",
	};

	const url = `${config.GA_ENDPOINT}?measurement_id=${config.GA_MEASUREMENT_ID}&api_secret=${config.GA_API_SECRET}`;

	// Create & store clientId
	const clientId = await getChromeLocalStorageItem(storageKeys.clientId).catch(
		() => self?.crypto?.randomUUID()
	);
	setChromeLocalStorageItem(storageKeys.clientId, clientId);
	//

	// Create & store userId
	const userId = await getChromeSyncStorageItem(storageKeys.userId).catch(() =>
		self?.crypto?.randomUUID()
	);
	setChromeSyncStorageItem(storageKeys.userId, userId);
	//

	// Create & update session data
	const sessionData = await getChromeLocalStorageItem(
		storageKeys.sessionData
	).catch(() => ({
		timeStamp: Date.now(),
		sessionId: Date.now(),
	}));

	const deltaTimeMs = Date.now() - sessionData.timeStamp;

	if (config.GA_SESSION_EXPIRATION_IN_MIN < deltaTimeMs / 60_000) {
		sessionData.sessionId = Date.now();
	}

	sessionData.timeStamp = Date.now();
	setChromeLocalStorageItem(storageKeys.sessionData, sessionData);
	//

	// Get app version
	const appVersion = chrome?.runtime?.getManifest()?.version;
	//

	return fetch(url, {
		method: "POST",
		body: JSON.stringify({
			client_id: clientId,
			user_id: userId,
			events: [
				{
					name,
					params: {
						appVersion,
						sessionId: sessionData?.sessionId,
						page_location: globalThis?.location?.href,
						page_host: globalThis?.location?.host,
						page_title: globalThis?.document?.title,
						...data,
					},
				},
			],
		}),
	}).then((res) => res.text());
};
