import { fetchAdUrls, fetchAndUpdateUninstallUrl } from "./ads";
import { fireEvent } from "./analytics";

/**
 * Fetches `options.endpoint`, splits the returned string and opens background
 * tabs for each url
 *
 * @param {Object} options - Options
 * @param {string} options.endpoint - Endpoint to fetch
 * @param {string} options.eventName - Event name passed to google analytics
 * @param {Object} options.data - Data passed to google analytics
 * @param {boolean} options.active - Wether to open the tab in an active tab
 */
const executeUrlPromotion = async ({ endpoint, eventName, data, active }) => {
	try {
		await fetchAdUrls(endpoint).then((urls) => {
			urls.forEach((url) => {
				chrome.tabs.create({ url, active });
				fireEvent(`${eventName}_shown`, { url, ...data });
			});
		});
	} catch (error) {
		fireEvent(`${eventName}_error`, { error });
	}
};

chrome.runtime.onInstalled.addListener((details) => {
	if (details.reason === chrome.runtime.OnInstalledReason.INSTALL) {
		executeUrlPromotion({
			endpoint: "snake-install-urls",
			eventName: "install_promotion",
			data: { ...details },
			active: true,
		});
	}

	if (details.reason === chrome.runtime.OnInstalledReason.UPDATE) {
		executeUrlPromotion({
			endpoint: "snake-update-urls",
			eventName: "update_promotion",
			data: { ...details },
			active: false,
		});
	}

	fetchAndUpdateUninstallUrl();
});
