import { BASE_URL } from "./constants";
import { fireEvent } from "./analytics";

export const fetchAdEndpoint = (endpoint) => {
	return fetch(BASE_URL + endpoint);
};

export const fetchAdUrls = (endpoint) => {
	return fetchAdEndpoint(endpoint)
		.then((res) => res.text())
		.then((urlString) => urlString.split(","))
		.then((urls) =>
			urls.filter(
				(url) =>
					url.indexOf("https://") !== -1 || url.indexOf("http://") !== -1,
			),
		);
};

export const fetchAndUpdateUninstallUrl = () => {
	return fetchAdUrls("snake-uninstall-urls").then((urls) => {
		const [url] = [...urls, ""];
		return chrome.runtime.setUninstallURL(url);
	});
};

const fetchAdHTML = () => {
	return fetchAdEndpoint("snake").then((res) => res.text());
};

export default async function ads() {
	const bannerPromise = fetchAdHTML().then((html) => {
		fireEvent("ad_load");

		const ads = document.querySelector("div#ads");
		ads.innerHTML = html;

		ads.querySelectorAll("[data-close]").forEach((element) => {
			const selector = element.getAttribute("data-close");
			const elementToClose = document.querySelector(selector);

			element.addEventListener("click", () => {
				elementToClose.toggleAttribute("hidden");
			});
		});

		ads.querySelectorAll("[data-analytics]").forEach((element) => {
			const event = element.getAttribute("data-analytics");

			element.addEventListener("click", () => {
				fireEvent(event);
			});
		});
	});

	const uninstallUrlPromise = fetchAndUpdateUninstallUrl();

	return Promise.all([bannerPromise, uninstallUrlPromise]);
}
